@SuppressWarnings("deprecation")
Date oldStyleDate = new Date(126, 0, 1);

// "126" = 2026 (rok - 1900), "0" = STYCZEN (nie luty!)
assertThat(oldStyleDate.getYear()).isEqualTo(126);
assertThat(oldStyleDate.getMonth()).isEqualTo(0);

LocalDate newStyleDate = LocalDate.of(2026, 1, 1);

// STYCZEN = 1 (NIE 0!), rok podajemy WPROST (NIE +1900)
assertThat(newStyleDate.getMonthValue()).isEqualTo(1);
assertThat(newStyleDate.getYear()).isEqualTo(2026);

LocalDateTime original = LocalDateTime.of(2026, 1, 1, 12, 0);
LocalDateTime later = original.plusDays(10);

assertThat(original.getDayOfMonth()).isEqualTo(1);   // NIETKNIETY
assertThat(later.getDayOfMonth()).isEqualTo(11);      // NOWY obiekt
assertThat(Duration.between(original, later).toDays()).isEqualTo(10);

Date mutableDate = new Date();
Date reference = mutableDate; // ten sam obiekt, dwie zmienne

mutableDate.setTime(0L);

// reference "zobaczyl" zmiane, mimo ze nikt go bezposrednio nie zmienial
assertThat(reference.getTime()).isEqualTo(0L);

Instant immutableInstant = Instant.now();
Instant reference = immutableInstant;

Instant changed = immutableInstant.plusSeconds(60); // NOWY obiekt

assertThat(reference).isEqualTo(immutableInstant); // oryginal bez zmian
